"  return { status: outcome.confirmation_status, note: outcome.confirmation_note, saved }\n}\n\n// A short notice that goes with the confirmation: \"received\" (a payment has arrived but the order is not accepted yet) or \"refused\" (the owner has refunded it).\n// Same rules as the confirmation: it NEVER throws; a REAL payment only gets it once the wording has been approved and the Resend key is set; what happened is written on the order\n// as notice_kind / notice_status (\"sent\", \"failed\" or \"not_sent\") / notice_note (sql/orders-notices.sql). If those columns are not there yet, the email still goes.\nexport async function sendNotice(kind, order, { env = process.env, fetchImpl, record = recordConfirmation, match, keySuffix = '', now = () => new Date() } = {}) {\n  const where = match || `stripe_session_id=eq.${encodeURIComponent(clean(order && order.stripe_session_id))}`\n  const fields = (status, note, at) => ({ notice_kind: kind, notice_status: status, notice_note: note, notice_sent_at: at })\n  let outcome\n  try {\n    const live = Boolean(order && order.livemode)\n    if (!NOTICE_KINDS.includes(kind)) {\n      outcome = fields('failed', 'Not sent: that kind of notice does not exist.', null)\n    } else if (!isEmailAddress(order && order.customer_email)) {\n      outcome = fields('not_sent', 'There is no usable email address on this payment, so no notice could be sent. Email the customer yourself.', null)\n    } else if (live && !WORDING_APPROVED) {\n      outcome = fields('not_sent', 'Not sent: the wording of the customer emails has not been approved yet. Email the customer yourself.', null)\n    } else if (!clean(env.RESEND_API_KEY)) {\n      outcome = fields('not_sent', 'Not sent: RESEND_API_KEY is not set in Vercel.', null)\n    } else {\n      const message = buildNotice(kind, order)\n      const sent = await sendEmail({ to: order.customer_email, ...message, idempotencyKey: `order-${kind}-${clean(order.stripe_session_id)}${keySuffix}` }, { env, fetchImpl })\n      outcome = sent.ok ? fields('sent', null, now().toISOString()) : fields('failed', `Not sent: ${sent.detail}`, null)\n    }\n  } catch (e) {\n    outcome = fields('failed', 'Not sent: something went wrong while preparing the email.', null)\n  }\n  let saved = false\n  try {\n    saved = await record(where, outcome)\n  } catch (e) {\n    saved = false\n  }\n  return { status: outcome.notice_status, note: outcome.notice_note, saved }\n}\n"
