"  return { result, patch, saved }\n}\n\n// Places an order that has ALREADY been claimed, writes the result, and then tells the customer the right thing (Gill, 21 October 2026). Under the Terms the contract begins when we\n// email the CONFIRMATION, so that goes only once Creative Hub has accepted the order. If it has not (it said no, or its answer was lost), the customer is told their payment has\n// arrived and that this is not yet the confirmation (\"received\"), once. Neither email can ever stop the other, the order, or the answer: nothing here throws.\nexport async function placeAndNotify(order, match, { fetchImpl, env = process.env, confirm = confirmOrder, notice = sendNotice } = {}) {\n  const placed = await placeAndRecord(order, match, { fetchImpl })\n  try {\n    const accepted = placed.patch.status === 'sent' && placed.saved && placed.saved.ok && placed.saved.rows.length === 1\n    if (accepted) {\n      if (order.confirmation_status !== 'sent') await confirm(order, { env, fetchImpl, match })\n    } else if (!(order.notice_kind === 'received' && order.notice_status === 'sent')) {\n      await notice('received', order, { env, fetchImpl, match })\n    }\n  } catch (e) {\n    // an email problem must never undo or hide what happened to the order\n  }\n  return placed\n}\n"
